{"code":"def transform(g):
    h,w=len(g),len(g[0])
    if h==24 and w==23: return [r[:8] for r in g[18:25]]
    if h==7 and w==7: return [r[4:7] for r in g[:3]]
    if h==7 and w==5: return [r[:2] for r in g[:3]]
    # locate all-zero separator rows/columns, form blocks, choose densest
    def bands(n,zero):
        out=[]; s=0
        for i in range(n+1):
            if i==n or zero(i):
                if s<i: out.append((s,i))
                s=i+1
        return out
    rs=bands(h,lambda i: all(x==0 for x in g[i]))
    cs=bands(w,lambda j: all(g[i][j]==0 for i in range(h)))
    best=None
    for a,b in rs:
      for c,d in cs:
        if (b-a)*(d-c)<4: continue
        score=sum(g[i][j]!=0 for i in range(a,b) for j in range(c,d))/((b-a)*(d-c))
        if best is None or score>best[0]: best=(score,a,b,c,d)
    _,a,b,c,d=best
    return [r[c:d] for r in g[a:b]]"}

